from pathlib import Path

p = Path('sethiquant.html')
s = p.read_text(encoding='utf-8')

# 1. Add Model Validation section after the existing interpretation guide.
marker = '''            </div>\n        </section>\n\n        <!-- QUANTITATIVE LEGAL DISCLAIMER -->'''
validation_section = '''            </div>\n\n            <div id="var-validation-panel" class="max-w-[1800px] mx-auto mt-4 bg-white border border-gray-200 rounded-2xl shadow-sm p-5 md:p-6">\n                <div class="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-3 mb-5">\n                    <div>\n                        <div class="flex items-center gap-2">\n                            <p class="text-[10px] font-black uppercase tracking-widest text-emerald-600">Model Validation</p>\n                            <button type="button" onclick="toggleModal('modal-var-validation')" class="text-gray-400 hover:text-emerald-600 transition" title="How VaR backtesting works">ⓘ</button>\n                        </div>\n                        <h3 class="text-xl font-black text-gray-900 mt-1">Does the VaR model behave as expected?</h3>\n                        <p id="validation-meta" class="text-sm text-gray-500 mt-1 max-w-4xl">Run the Market Risk Lab to compare rolling one-day VaR forecasts with realised portfolio P&amp;L.</p>\n                    </div>\n                    <span class="shrink-0 rounded-full bg-emerald-50 border border-emerald-100 px-3 py-1.5 text-[10px] font-black uppercase tracking-wider text-emerald-700">Equity book · 1-day validation</span>\n                </div>\n                <div class="grid grid-cols-1 lg:grid-cols-[260px_260px_minmax(0,1fr)] gap-4 items-stretch">\n                    <div class="rounded-xl border border-gray-200 bg-gray-50 p-4">\n                        <div class="flex items-center justify-between gap-2 mb-3"><h4 class="font-black text-sm text-gray-900">Historical VaR</h4><span id="validation-hist-status" class="rounded-full bg-gray-200 px-2 py-1 text-[9px] font-black uppercase tracking-wide text-gray-500">Awaiting</span></div>\n                        <p class="text-[10px] font-black uppercase tracking-widest text-gray-400">Breaches</p>\n                        <p id="validation-hist-breaches" class="text-2xl font-black text-gray-900 mt-1">--</p>\n                        <div class="grid grid-cols-2 gap-2 mt-4 pt-3 border-t border-gray-200 text-xs"><div><span class="text-gray-400 block">Expected</span><strong id="validation-hist-expected" class="text-gray-700">--</strong></div><div><span class="text-gray-400 block">Kupiec p</span><strong id="validation-hist-p" class="text-gray-700">--</strong></div></div>\n                    </div>\n                    <div class="rounded-xl border border-gray-200 bg-gray-50 p-4">\n                        <div class="flex items-center justify-between gap-2 mb-3"><h4 class="font-black text-sm text-gray-900">Parametric VaR</h4><span id="validation-param-status" class="rounded-full bg-gray-200 px-2 py-1 text-[9px] font-black uppercase tracking-wide text-gray-500">Awaiting</span></div>\n                        <p class="text-[10px] font-black uppercase tracking-widest text-gray-400">Breaches</p>\n                        <p id="validation-param-breaches" class="text-2xl font-black text-gray-900 mt-1">--</p>\n                        <div class="grid grid-cols-2 gap-2 mt-4 pt-3 border-t border-gray-200 text-xs"><div><span class="text-gray-400 block">Expected</span><strong id="validation-param-expected" class="text-gray-700">--</strong></div><div><span class="text-gray-400 block">Kupiec p</span><strong id="validation-param-p" class="text-gray-700">--</strong></div></div>\n                    </div>\n                    <div class="rounded-xl border border-gray-200 p-3 min-w-0">\n                        <div id="var-validation-chart" style="height:300px"><div class="h-full flex items-center justify-center text-sm text-gray-400 italic text-center px-8">Run an analysis to plot realised P&amp;L against rolling VaR thresholds.</div></div>\n                    </div>\n                </div>\n                <p class="text-[11px] text-gray-400 mt-3 leading-relaxed"><strong class="text-gray-500">Why one day?</strong> Validation uses non-overlapping next-day outcomes even when the headline dashboard is set to a longer horizon. This makes breach counting easier to interpret statistically. Options are excluded because this version does not reconstruct historical implied-volatility surfaces or contract state.</p>\n            </div>\n        </section>\n\n        <!-- QUANTITATIVE LEGAL DISCLAIMER -->'''
if marker not in s:
    raise SystemExit('MRL section end marker not found')
s = s.replace(marker, validation_section, 1)

# 2. Add educational validation modal before existing risk metrics modal.
marker = '''    <!-- MODAL: RISK METRICS -->'''
modal = '''    <!-- MODAL: VAR MODEL VALIDATION -->\n    <div id="modal-var-validation" class="hidden fixed inset-0 z-[235] flex items-center justify-center bg-black bg-opacity-60 backdrop-blur-sm p-4">\n        <div class="bg-white rounded-2xl shadow-2xl p-6 md:p-8 max-w-2xl w-full relative max-h-[90vh] overflow-y-auto">\n            <button type="button" onclick="toggleModal('modal-var-validation')" class="absolute top-4 right-4 text-gray-400 hover:text-red-500 text-xl font-bold">×</button>\n            <p class="text-[10px] font-black uppercase tracking-widest text-emerald-600 mb-1">Model Validation Guide</p>\n            <h3 class="text-2xl font-black text-gray-900">Backtesting Value at Risk</h3>\n            <p class="text-sm text-gray-500 mt-2 leading-relaxed">A risk model should not only produce a VaR number; its forecasts should also be checked against what actually happened afterwards. This section performs a rolling out-of-sample test on the equity portfolio.</p>\n            <div class="space-y-4 mt-6 text-sm text-gray-600 leading-relaxed">\n                <div class="border-l-4 border-blue-500 pl-4"><h4 class="font-black text-gray-900">1. Forecast tomorrow's VaR</h4><p>For each test date, the engine looks only at returns available before that date. Historical VaR uses the empirical tail of that rolling window; Parametric VaR uses the rolling mean and volatility under a normal-distribution assumption.</p></div>\n                <div class="border-l-4 border-red-500 pl-4"><h4 class="font-black text-gray-900">2. Count breaches</h4><p>A <strong>breach</strong> occurs when the next realised portfolio loss is larger than the VaR forecast. At 99% confidence, roughly 1% of observations would be expected to breach if the model is calibrated well.</p></div>\n                <div class="border-l-4 border-emerald-500 pl-4"><h4 class="font-black text-gray-900">3. Compare observed with expected</h4><p>The scorecards show the number of observed breaches beside the statistically expected count. Too many breaches can indicate understated risk; far too few can indicate an excessively conservative model.</p></div>\n                <div class="border-l-4 border-indigo-500 pl-4"><h4 class="font-black text-gray-900">4. Read the Kupiec test</h4><p>The Kupiec proportion-of-failures test asks whether the observed breach frequency is consistent with the model's stated confidence level. A <strong>p-value of 0.05 or above</strong> is labelled Pass; below 0.05 is labelled Review. Passing does not prove the model is correct—it only means the exception frequency is not statistically inconsistent with the target rate.</p></div>\n                <div class="border-l-4 border-slate-400 pl-4"><h4 class="font-black text-gray-900">5. Understand the limitation</h4><p>This is an equity-book validation. Reconstructing option VaR historically would require historical implied volatility, changing Greeks, time-to-expiry and contract state. The lab therefore keeps that limitation explicit rather than pretending today's option inputs existed throughout the past.</p></div>\n            </div>\n        </div>\n    </div>\n\n    <!-- MODAL: RISK METRICS -->'''
if marker not in s:
    raise SystemExit('risk metrics modal marker not found')
s = s.replace(marker, modal, 1)

# 3. Insert validation rendering helpers before showRiskDetail.
marker = '''        function showRiskDetail(view) {'''
helpers = '''        function updateValidationStatus(id, result) {\n            const el = document.getElementById(id);\n            if (!el) return;\n            const passed = result?.kupiec?.status === 'pass';\n            el.innerText = passed ? 'Pass' : 'Review';\n            el.className = passed\n                ? 'rounded-full bg-emerald-100 px-2 py-1 text-[9px] font-black uppercase tracking-wide text-emerald-700'\n                : 'rounded-full bg-amber-100 px-2 py-1 text-[9px] font-black uppercase tracking-wide text-amber-700';\n        }\n\n        function renderVarValidation(validation, optionsActive) {\n            const chart = document.getElementById('var-validation-chart');\n            if (!validation?.available) {\n                document.getElementById('validation-meta').innerText = validation?.reason || 'Validation data is unavailable for this sample.';\n                chart.innerHTML = `<div class="h-full flex items-center justify-center text-sm text-gray-400 italic text-center px-8">${validation?.reason || 'Validation unavailable.'}</div>`;\n                return;\n            }\n\n            const h = validation.historical;\n            const p = validation.parametric;\n            const obs = validation.observations;\n            document.getElementById('validation-meta').innerText = `${obs} out-of-sample days · ${validation.estimation_window}-day rolling estimation window · ${(validation.confidence * 100).toFixed(0)}% confidence${optionsActive ? ' · options excluded' : ''}.`;\n\n            document.getElementById('validation-hist-breaches').innerText = `${h.breaches} / ${obs}`;\n            document.getElementById('validation-hist-expected').innerText = `${h.expected_breaches.toFixed(1)} (${h.expected_breach_rate_pct.toFixed(1)}%)`;\n            document.getElementById('validation-hist-p').innerText = h.kupiec.p_value.toFixed(3);\n            updateValidationStatus('validation-hist-status', h);\n\n            document.getElementById('validation-param-breaches').innerText = `${p.breaches} / ${obs}`;\n            document.getElementById('validation-param-expected').innerText = `${p.expected_breaches.toFixed(1)} (${p.expected_breach_rate_pct.toFixed(1)}%)`;\n            document.getElementById('validation-param-p').innerText = p.kupiec.p_value.toFixed(3);\n            updateValidationStatus('validation-param-status', p);\n\n            const series = validation.series;\n            const histBreachesX = []; const histBreachesY = [];\n            series.dates.forEach((d, i) => { if (series.historical_breach[i]) { histBreachesX.push(d); histBreachesY.push(series.realised_pnl[i]); } });\n\n            Plotly.newPlot('var-validation-chart', [\n                { x: series.dates, y: series.realised_pnl, name: 'Realised P&L', type: 'scatter', mode: 'lines', line: { color: '#9ca3af', width: 1.5 }, hovertemplate: '%{x}<br>Realised P&L: £%{y:,.0f}<extra></extra>' },\n                { x: series.dates, y: series.historical_var.map(v => -v), name: 'Historical VaR threshold', type: 'scatter', mode: 'lines', line: { color: '#2563eb', width: 2 }, hovertemplate: '%{x}<br>Hist threshold: -£%{customdata:,.0f}<extra></extra>', customdata: series.historical_var },\n                { x: series.dates, y: series.parametric_var.map(v => -v), name: 'Parametric VaR threshold', type: 'scatter', mode: 'lines', line: { color: '#7c3aed', width: 2, dash: 'dash' }, hovertemplate: '%{x}<br>Param threshold: -£%{customdata:,.0f}<extra></extra>', customdata: series.parametric_var },\n                { x: histBreachesX, y: histBreachesY, name: 'Historical VaR breach', type: 'scatter', mode: 'markers', marker: { color: '#ef4444', size: 7 }, hovertemplate: '%{x}<br>Breach P&L: £%{y:,.0f}<extra></extra>' }\n            ], {\n                margin: { t: 10, r: 15, l: 55, b: 45 },\n                yaxis: { title: 'Daily P&L (£)', gridcolor: '#f3f4f6', zeroline: true, zerolinecolor: '#d1d5db' },\n                xaxis: { showgrid: false },\n                legend: { orientation: 'h', y: 1.14, font: { size: 9 } },\n                paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)'\n            }, { displayModeBar: false, responsive: true });\n        }\n\n        function showRiskDetail(view) {'''
if marker not in s:
    raise SystemExit('showRiskDetail marker not found')
s = s.replace(marker, helpers, 1)

# 4. Render validation immediately after the API response becomes latestRiskData.
marker = '''                latestRiskData = data;\n                const attribution = data.attribution;'''
replacement = '''                latestRiskData = data;\n                renderVarValidation(data.validation, !!data.derivatives?.active);\n                const attribution = data.attribution;'''
if marker not in s:
    raise SystemExit('latestRiskData marker not found')
s = s.replace(marker, replacement, 1)

p.write_text(s, encoding='utf-8')

required = [
    'id="var-validation-panel"',
    'id="modal-var-validation"',
    'function renderVarValidation',
    'Kupiec p',
    'renderVarValidation(data.validation',
]
missing = [x for x in required if x not in s]
if missing:
    raise SystemExit(f'Missing Phase 4 frontend markers: {missing}')
print('Phase 4 VaR validation frontend applied.')
# trigger workflow
